quests[9013] = { title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, $n! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Ihr habt durch Eure Taten die Sünden unserer Vergangenheit gesühnt.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", objectives = "Gebt Mokvar Euren Helm der Ehre und Eure Brustplatte der Ehre.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
