quests[9023] = { title = "Das perfekte Gift", description = "Mein Bruder und ich sind im Rabenholdtanwesen für den Giftbedarf zuständig.\n\nLord Rabenholdt hat mich damit beauftragt, eine neue und extrem effektive Giftmischung zusammenzustellen, die aus den Giftbeuteln der Bewohner von Zul'Gurub und den Ruinen von Ahn'Qiraj gewonnen werden kann.\n\nEs gibt in diesen verfluchten Ruinen zwei ganz besonders giftige Bestien, die vielleicht genau das haben, wonach wir suchen, $C. Bringt mir einen Giftbeutel der Bestien Kurinnaxx und Venoxis und wir wären Euch ewig dankbar.", objectives = "Dirk Donnerholz in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9024] = { title = "Aristans Verdacht", description = "Ich hab's! Habt Ihr den neuen Duft in den Straßen aufgeschnappt? Das neue Duftwasser und Parfüm, das gerade so angesagt ist? Unsere Wachen würden ihre Pflichten nicht so einfach vernachlässigen.\n\nZumindest nicht, solange ihre Sinne nicht von fauler Alchemie vernebelt wurden.\n\nEs gibt nur einen Weg, um ganz sicher zu sein - bringt Morgan Pestle einen Flakon von dem Parfüm und dem Duftwasser, und klärt ihn über meinen Verdacht auf. Ich werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", objectives = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Morgan Pestle im Handelsdistrikt von Sturmwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9025] = { title = "Morgans Entdeckung", description = "Nun... es sieht ganz so aus, als ob Aristan doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in Liebestränken und Gedanken verwirrenden Gebräuen verwendet werden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig.", objectives = "Kehrt zu Aristan Mottar zurück, er befindet sich vor der Bank im Handelsdistrikt von Sturmwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9026] = { title = "Verfolgung der Spur", description = "Wir müssen der Ursache auf den Grund gehen. Ich habe viel mehr Leute als sonst - einschließlich Wachen - im Gasthaus 'Die güldene Rose' ein- und ausgehen sehen. Sprecht mit Allison, sollte sie verkaufen, so kann sie Euch zu der Herkunft der Ware Auskunft geben.", objectives = "Sprecht mit Gastwirtin Allison im Gasthaus 'Die güldene Rose' im Handelsdistrikt von Sturmwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9027] = { title = "Verfolgung der Spur", description = "Irgendwas mit dem Duftwasser? Das ist möglich. Ich habe noch nie gesehen, dass eine Ware so begehrt war wie diese.\n\nHört mal, sollte es etwas damit auf sich haben, dann möchte ich es auch wissen. Ich habe meine Lieferung von einem Händler namens Evert Sorisam. Er ist neu in der Stadt.\n\nEr erwähnte, dass er einige Waren hätte, die er bei 'Das feinste Band' abliefern müsse.", objectives = "Sprecht mit Evert Sorisam bei 'Das feinste Band' entlang der Kanäle Sturmwinds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9028] = { title = "Lüftung des Geheimnisses", description = "Was? Verrat? Nein, nein. Ich versichere Euch, dass meine Absichten in jeder Hinsicht harmlos sind.\n\nIst es denn so falsch, denen helfen zu wollen, die dieses leidvolle Ritual des Umwerbens zu erleichtern wünschen? Kommt schon, das ist doch kein Verbrechen.\n\nIch werde Euch beweisen, dass ich keine schlechten Absichten hege, indem ich Euch meine Quelle verrate.\n\nDie Lieferung wurde mir von einem Staffron Lerent zugestellt, so eine Art Apotheker. Ich habe nie mit ihm gesprochen.\n\nUnser Goblinmittelsmann meinte, dass er im Vorgebirge des Hügellands gearbeitet hätte, irgendwo hinter dem unheimlichen Rabenholdtanwesen. Ich wünsche Euch viel Glück bei der Suche nach ihm.", objectives = "Findet Apotheker Staffron Lerent hinter dem Rabenholdtanwesen im Vorgebirge des Hügellands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9029] = { title = "Ein blubbernder Kessel", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9032] = { title = "Bodleys trauriges Schicksal", description = "Das Amulett enthielt Lord Valthalaks Seele? Dann ist es nicht weiter verwunderlich, dass es mit einem solch machtvollen Fluch belegt war.\n\nBodley aufzufinden, könnte sich allerdings schwierig gestalten. Als ich das letzte Mal von ihm hörte, wollte er in die Schwarzfelsspitze zurückkehren. Seitdem hat niemand jemals wieder etwas von ihm gehört.\n\nSucht ihn in der Schwarzfelsspitze, aber ich befürchte, dass er bereits tot ist. Ich würde Euch empfehlen, den Apparat des Goblins mitzunehmen.", objectives = "Reist zum Schwarzfels und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Schwarzfelsspitze zu finden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9033] = { title = "Echo des Krieges", description = "Fünf Jahre sind seit dem letzten Krieg vergangen...\n\nZehntausende mussten dabei ihr Leben lassen - und für was? Die Bedrohung wurde niemals gänzlich ausgelöscht.\n\nJetzt verbreitet der Lichkönig erneut Angst und Schrecken... sein getreuer Jünger, Kel'Thuzad, zieht seine Truppen für einen weiteren Angriff auf unser Land zusammen.\n\nWir werden es nicht zulassen! Beweist Euer Engagement. Zeigt, dass Ihr gewillt seid, Leib und Leben zu riskieren, um diesen Wahnsinn aufzuhalten! Die vereinigte Macht der Argentumdämmerung und des Kreuzzugs wird Euch mit allen Mitteln zur Seite stehen.\n\nGeht nach Naxxramas und zerstört die Geißel...", objectives = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte, dass Ihr 5 lebende Monstrositäten, 5 Steinhautgargoyles, 8 Hauptmänner der Todesritter und 3 Giftpirscher tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9034] = { title = "Brustplatte des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", objectives = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Brustplatte des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9036] = { title = "Beinplatten des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", objectives = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Beinplatten des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinplatten, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
