quests[9043] = { title = "Tunika der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", objectives = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
