quests[9050] = { title = "Handgelenksschützer der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", objectives = "Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch ein Paar Handgelenksschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Handgelenksschützer, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9051] = { title = "Giftexperiment", description = "Das Gift, das Ihr mir geholfen habt zu entwickeln, ist für einen bestimmten Zweck gedacht. Die mächtigen Teufelssaurier des Kraters erschweren mir die Jagd und das Überleben. Selbst wenn ich über die nötige Stärke verfügen würde, einen Teufelssaurier zu erlegen, würde einfach nur ein anderer sein Territorium beanspruchen.\n\nNehmt diesen vergifteten Widerhaken und stecht ihn tief in einen lebenden Teufelssaurier. Das Gift sollte ihn ruhigstellen, aber ich bin mir nicht sicher, wie lange es dauern wird, bis es wirkt...", objectives = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken und kehrt danach zu Torwa Pfadfinder im Krater von Un'Goro zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9052] = { title = "Blutblütengift", description = "Ich würde Euch darum bitten, mir dabei behilflich zu sein, ein spezielles Gift zu entwickeln, um eine der mächtigsten Kreaturen des Kraters ruhigzustellen. Es ist nicht tödlich und nur $gein:eine:c; $C mit scharfen Augen kann die nötigen Zutaten dafür erspähen.\n\nDie Blutkappenpilze wachsen in den Blutblütensprösslingen, die überall im Krater anzufinden sind. Gorishistachel könnt Ihr von den Insekten erhalten, die in der und um die Wuchernde Narbe herum heimisch sind. Sie befindet sich im südlichen Teil des Kraters.", objectives = "Sammelt 8 Blutkappenpilze und 8 Gorishistachel und kehrt zu Torwa Pfadfinder im Krater von Un'Goro zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9053] = { title = "Eine bessere Zutat", description = "Genau wie ich befürchtet hatte - das Gift ist einfach zu schwach für eine solch mächtige Kreatur.\n\nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal'Hakkar begeben müssen. Enträtselt dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", objectives = "Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des Versunkenen Tempels und kehrt zu Torwa Pfadfinder zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9054] = { title = "Tunika des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", objectives = "Jäger Leopold bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
