quests[9063] = { title = "Torwa Pfadfinder", description = "Ein Jäger namens Torwa Pfadfinder hat die Hilfe eines Druiden angefordert. Er sagte, dass nur einer von uns über den nötigen Respekt für die Natur und die Fähigkeiten verfügen würde, um ihm zu helfen.\n\nEs gibt einen Pfad, der den Krater von Un'Goro und die Tanariswüste verbindet. Ihr werdet Torwa nahe dem Punkt finden, an dem der Pfad in den Krater hineinführt.", objectives = "Sprecht im Krater von Un'Goro mit Torwa Pfadfinder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9068] = { title = "Tunika des Erdspalters", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.", objectives = "Rimblat Erdspalter bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Tunika des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
