quests[9094] = { title = "Handschuhe der Argentumdämmerung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9095] = { title = "Frostfeuerrobe", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für mich die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.", objectives = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Frostfeuerrobe anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
