quests[9110] = { title = "Bindungen des verseuchten Herzens", description = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören. Dies erklärt den äußerst hohen Preis. Sollte ich sterben, so werde ich zumindest als reicher Mann dahinscheiden.\n\nEs kümmert mich einen Ogerdreck als was Ihr sterbt, Hauptsache Ihr macht, was ich von Euch verlange. Bringt mir die benötigten Dinge und wir werden beide davon profitieren - oder sterben; aber das habe ich ja bereits erklärt...", objectives = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Bindungen des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9111] = { title = "Robe des Glaubens", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n$g Gesegneter Junge:Gesegnetes Mädchen;, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", objectives = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Robe des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9112] = { title = "Gamaschen des Glaubens", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n$g Gesegneter Junge:Gesegnetes Mädchen;, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", objectives = "Vater Inigo Montoy bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Gamaschen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Gamaschen, 20 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
