quests[9120] = { title = "Der Niedergang Kel'Thuzads", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des Hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", objectives = "Bringt Kel'Thuzads Phylakterium zu der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9121] = { title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von arkaner Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Da es an Eurer Hingabe für die Ziele der Argentumdämmerung noch etwas mangelt, $N, wird der Preis hoch sein. Es steht Euch frei abzulehnen und noch einmal für einen günstigeren Preis wiederzukehren, sobald Euer Ruf respektvoll oder ehrfürchtig ist.", objectives = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 Arkankristalle, 2 Nexuskristalle, 1 rechtschaffene Kugel und 60 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem wohlwollend sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9122] = { title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung bewundernswert ist, sind wir gewillt, einige dieser Kosten für Euch zu übernehmen.", objectives = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 2 Arkankristalle, 1 Nexuskristall und 30 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem respektvoll sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9123] = { title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch, dort hineinzugelangen, von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichtegemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mithilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können – einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.", objectives = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9124] = { title = "Was man für Gruftpirscherrüstung braucht...", description = "Würdet Ihr Euch gerne eine dieser glänzenden Münzen verdienen?\n\n<Leopold hält eine Insignie des Kreuzzugs in die Höhe.>\n\nIch habe ein kleines Problem, bei dem Ihr mir vielleicht behilflich sein könntet, $N. Seht Ihr, ich fertige Gruftpirscherrüstung für diejenigen an, die dämlich genug sind, um sich nach Naxxramas zu wagen. Während sie mich mit den wichtigsten Bestandteilen für die Rüstung versorgen, gehen mir dennoch ständig die Teile von Gruftsatanskreaturen aus. Bringt mir einen Schwung dieser Teile und ich werde Euch dafür mit einer Insignie bezahlen - einlösbar bei dem Rüstmeister.", objectives = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Teile einer Gruftsatanskreatur.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9125] = { title = "Teile einer Gruftbestie", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9126] = { title = "Knochensensenjagd", description = "Don Julios Muster für die Rüstung der Knochensense benötigt Knochenfragmente - ein Menge Knochenfragmente. Diejenigen, die verrückt genug sind, um sich nach Naxxramas zu wagen, versorgen mich bereits mit den wichtigsten Bestandteilen für die Rüstung. Allerdings halte ich stets nach weiteren Knochenfragmenten Ausschau.\n\nWas denkt Ihr? Würdet Ihr Euch gerne die Hände schmutzig machen und dabei ein paar Anhänger der Geißel vernichten? Hierbei kommt jeder gut davon.", objectives = "Rohan der Assassine bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Knochenfragmente.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9127] = { title = "Knochenfragmente", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9128] = { title = "Die Elementargleichung", description = "Seid gegrüßt, Abenteurer! Hättet Ihr Interesse an Arbeit? Wer für mich arbeitet, wird mit Insignien bezahlt. Diese Insignien können beim Rüstmeister für mächtige Gegenstände eingetauscht werden.\n\nEure Aufgabe besteht darin, mir so viele Kerne der Elemente zu bringen, wie Ihr tragen könnt. Je mehr, umso besser!\n\nIhr findet sie bei Elementaren verschiedenster Form und Größe, wie es sie überall in unserer Welt gibt.", objectives = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Kerne der Elemente.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9129] = { title = "Kern der Elemente", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9131] = { title = "Bindung des Schreckenspanzers", description = "Habt Ihr jemals eine Rüstung des Schreckenspanzers zu Gesicht bekommen, $C? Nein, natürlich nicht. Ihr seid immer noch ein $g Junge:Mädchen; - ein Dreikäsehoch eben. Ich muss Euch sagen, es ist herrlich.\n\nIhr fragt Euch wahrscheinlich was all das mit Euch zu tun haben soll, richtig? Hört gut zu, Anfänger; ich brauche Dunkeleisenfragmente und bin bereit zu zahlen, um an so viele Stücke wie möglich zu kommen.\n\nIch benötige die Fragmente für das Zusammensetzen der Schreckenspanzer für unsere Helden. Bringt mir Fragmente, dann werdet Ihr bezahlt.", objectives = "Korfax bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Dunkeleisenfragmente.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9132] = { title = "Dunkeleisenfragmente", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9136] = { title = "Wildpflanzen", description = "Ich fertige für die mutigen Helden, die sich nach Naxxramas begeben, eine spezielle Rüstung an - die Rüstung des Traumwandlers. Sie versorgen mich zwar schon mit den meisten Materialien, die ich dafür benötige, aber ich halte dennoch nach jenen Ausschau, die in der Lage sind, mir Wildwedel aus dem Pflanzenreich unserer Welt zu besorgen.\n\nIhr denkt vielleicht, dass diese Aufgabe unter Eurer Würde ist, aber ohne diese Wedel kann die Rüstung nun mal nicht hergestellt werden.\n\nIch bin außerdem in der einzigartigen Lage, Euch mit einer Insignie Eurer Wahl zu bezahlen, da mich die Argentumdämmerung und der Kreuzzug mit den entsprechenden Mitteln unterstützen.", objectives = "Rayne bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 30 Wildwedel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9137] = { title = "Wildwedel", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9141] = { title = "Sie nennen mich \"den Schleifer\"", description = "Ihr wollt eine Verfügung? Ihr erwartet von mir, Euch eine heißbegehrte Arbeitsanweisung einfach so auszuhändigen? Ich glaube nicht, Knirps. Handwerker aus der ganzen Welt bewerben sich um Aufträge hier an der Front.\n\nWenn Ihr eine Arbeitsanweisung wollt, zeigt mir, dass Ihr gewillt seit, für die Sache zu bluten! Bringt mir eine Ehrenmarke, dann können wir darüber reden.\n\nUnd es gibt nur einen Weg, so eine Marke in Eure schmutzigen kleinen Pfoten zu bekommen - geht kämpfen.", objectives = "Einsatzkommandant Metz in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte eine Ehrenmarke der Argentumdämmerung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9142] = { title = "Handwerksverfügung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9153] = { title = "Bedrohliche Schatten", description = "Die schwebenden Nekropolen der Geißel setzen die Territorien der Horde genauso unter Druck wie die der Allianz. Tanaris, die Verwüsteten Lande, Winterquell und die Brennende Steppe erzittern unter den Schatten der fliegenden Festungen.\n\nNur durch unser gemeinsames Handeln können wir sie zurückschlagen.\n\nJede Nekropole wird durch magische Zirkel unterstützt, die sich in der Nähe befinden und um die sich ein Schwarm untoter Kreaturen versammelt. Wir haben herausgefunden, dass wir die Verteidigung rund um die Zirkel zerstören können, indem wir die geistlosen Horden vernichten.", objectives = "Benutzt Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die Truppen der Geißel, die sie umgeben, besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9154] = { title = "Kapelle des Hoffnungsvollen Lichts", description = "Die Geißel ist in größerer Anzahl zurückgekehrt, als wir es jemals zuvor gesehen haben. Dies müssen die Machenschaften des Lichkönigs sein! Deshalb rekrutiert die Argentumdämmerung alle Männer und Frauen, die fähig und bereit sind, unsere Länder zu verteidigen.\n\nFalls Ihr unserer Sache dienen wollt, dann bringt dieses Dokument zum Bewahrer der Schriften bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", objectives = "Bringt den Ruf zu den Waffen zum Bewahrer der Schriften in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9165] = { title = "Verfügung des freien Geleits", description = "Ohne die Hilfe von Euch Abenteurern, hätte meine Karawane es niemals geschaft! Die Geißelsoldaten, die uns im Unterholz aufgelauert haben, wollten wohl nicht, dass wir hier in einem Stück eintreffen.\n\n<Wache Didier wischt sich den Schweiß von der Stirn.>\n\nJetzt werden wir erst einmal hier warten, bis Feldmarschall Chambers eintrifft. Er wird Eure Verfügung für freies Geleit unterzeichnen, die Ihr dann zu Einsatzkommandant Metz an der Kapelle des hoffnungsvollen Lichts bringen könnt.\n\nUnd $N, achtet in der Gegenwart von Chambers auf Eure Worte. Er ist ein Mensch der Sorte 'Ich reiße Euch den Kopf ab und breche Euch sämtliche Knochen'... mit dem Unterschied, dass er es auch wirklich tut...", objectives = "Bringt die unterschriebene Verfügung des freien Geleits zu Einsatzkommandant Metz an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9178] = { title = "Handwerksverfügung - Verdichteter Gewichtsstein", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-091:\n\n120 verdichtete Gewichtssteine.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", objectives = "Bringt 120 verdichtete Gewichtssteine und die Handwerksverfügung für die verdichteten Gewichtssteine zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
