quests[9204] = { title = "Handwerksverfügung - Steinschuppenaal", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-5:\n\n40 Steinschuppenaale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", objectives = "Bringt 40 Steinschuppenaale und die Handwerksverfügung für die Steinschuppenaale zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9205] = { title = "Handwerksverfügung - Panzerfisch", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-12:\n\n30 Panzerfische.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", objectives = "Bringt 30 Panzerfische und die Handwerksverfügung für die Panzerfische zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9206] = { title = "Handwerksverfügung - Zitteraal", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-9:\n\n30 Zitteraale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", objectives = "Bringt 30 Zitteraale und die Handwerksverfügung für die Zitteraale zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9208] = { title = "Der Greuelwächter - Arkanum des Schutzes", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", objectives = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Schutzes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9209] = { title = "Der Greuelwächter - Arkanum der Schnelligkeit", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", objectives = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum der Schnelligkeit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9210] = { title = "Der Greuelwächter - Arkanum des Fokus", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", objectives = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Fokus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9211] = { title = "Der Eiswächter", description = "Ah, der Eiswächter. Es ist ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Eiswächter verleiht jenen, die gegen Kreaturen von Frost und Eis kämpfen, erhöhten Schutz vor deren Angriffen.\n\nWie bei allem anderen auch, das vom Zornwirker hergestellt wird, so hat auch dieses Stück seinen Preis - einen Preis, der nicht diskutiert werden kann, wie viel Ihr Euch auch beklagen mögt. Interesse?", objectives = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9213] = { title = "Der Schattenwächter", description = "Das Machwerk eines Genies! Wie beim Eiswächter, ist es auch beim Schattenwächter ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Schattenwächter wird Euch genauso wie der Eiswächter einen guten Batzen Geld kosten.\n\n<Mataus streckt seine Hand aus und reibt seine Finger aneinander.>\n\nInteresse?", objectives = "Mataus der Zornwirker bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9221] = { title = "Überragende Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", objectives = "Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9222] = { title = "Epische Kampfausrüstung - Freund der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", objectives = "Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9223] = { title = "Überragende Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem ziemlich unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", objectives = "Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9224] = { title = "Epische Kampfausrüstung - Wohlwollen der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem extrem unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", objectives = "Für 75 Insignien der Dämmerung und 75 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9225] = { title = "Epische Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen respektvollen Ruf genießt, muss für epische Gegenstände noch immer einen sehr hohen Preis bezahlen. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.", objectives = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9226] = { title = "Überragende Kampfausrüstung - Respekt der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen respektvollen Ruf genießt, kann Gegenstände zu einem recht angemessenem Preis erwerben. Ich würde Euch zu einem Geschäft raten!", objectives = "Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9227] = { title = "Überragende Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen einen Preisnachlass. Ich würde Euch zu einem Geschäft raten!", objectives = "Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9228] = { title = "Epische Kampfausrüstung - Ehrfurcht der Dämmerung", description = "Seid gegrüßt, $gmein Freund:meine Freundin;. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass. Ich würde Euch zu einem Geschäft raten.", objectives = "Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9229] = { title = "Ramaladnis Schicksal", description = "Ramaladni war ein Krieger der Bruderschaft; er war ein Schüler von Hochlord Mograine bevor die Dämmerung überhaupt existierte! Als ihn die Nachricht von Mograines Tod erreichte, wurde er von Wut und Hass überwältigt.\n\nVersteht bitte, $n, wenn Wut und der Drang nach Vergeltung von jemandem Besitz ergreifen, hört er auf, ein Mensch zu sein, und wird stattdessen zur Verkörperung der Emotionen, die ihn beherrschen. Und so geschah es, dass Ramaladni, beseelt vom Geist der Vergeltung, Naxxramas betrat um Rache zu üben... und niemals zurückkehrte.\n\nBetretet Naxxramas und findet heraus, was mit Ramaladni geschah.", objectives = "Betretet Naxxramas und bringt Ramaladnis Schicksal in Erfahrung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9230] = { title = "Ramaladnis eisiger Griff", description = "Den Ring wiederherzustellen, scheint eine ziemliche Herausforderung zu sein, $n. Seht ihr, er wurde hergestellt aus Runen, die sich in Bauwerken der Geißel finden - in Bauwerken wie Naxxramas. Es könnten noch weitere Materialien gebraucht werden, aber Eure Hauptsorge sollte es sein, diese gefrorenen Runen zu beschaffen. Ich kann dem Ring seinen alten Glanz zurückgeben, wenn ihr mir bringt, was ich dazu benötige.", objectives = "Korfax in der Kapelle des Hoffnungsvollen Lichtes möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9232] = { title = "Das Einzige, das ich kann...", description = "Ihr haltet Euch für einen Helden der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?\n\n<Wilhelm seufzt.>\n\nPah, was für eine Wahl habe ich denn? Ihr seid das Beste, das ich zur Verfügung habe; warum sollte ich Euch nicht helfen?\n\nOmarion hat mir einen Plan hinterlassen. Es ist das Einzige, das ich kann... Ich kann ein paar Varianten dieser Hosen herstellen, Ihr müsst mich nur mit den Materialien versorgen.", objectives = "Handwerker Wilhelm in der Kapelle des Hoffnungsvollen Lichts möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9233] = { title = "Omarions Leitfaden", description = "Wilhelm,\n\nsolltet Ihr das hier lesen, bin ich bereits tot - endlich. Ihr sollt wissen, dass meine letzten Gedanken vor dem Tod Euch und Eurer Unfähigkeit als Handwerker galten. Unglücklicherweise besitzt der Überbringer dieses Leitfadens noch weniger Geschick als Ihr.\n\nZu dem Buch: Es beinhaltet meine letzten Anleitungen. Fertigt dem Überbringer dieses Leitfadens an, was immer dieser wünschen mag. Ich bin mir sicher, dass Ihr ein saftiges Honorar für Eure Dienste verlangen werdet, denn im Grunde seid Ihr nun mal ein Gauner.\n\nVerachtungsvoll,\n\nOmarion", objectives = "Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9234] = { title = "Eisfluchstulpen", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisfluchstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9235] = { title = "Eisflucharmschienen", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisflucharmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9236] = { title = "Eisfluchbrustplatte", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisfluchbrustplatte herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 16 Thoriumbarren, 2 Arkanitbarren, 4 Essenzen des Wassers und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9237] = { title = "Gletscherumhang", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, einen Gletscherumhang herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 4 Runenstoffballen, 2 Essenzen des Wassers, 4 Einheiten Eisenweberseide und 200 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9238] = { title = "Gletscherhandschutz", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, einen Gletscherhandschutz herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 2 Runenstoffballen, 2 Essenzen des Wassers, 2 Einheiten Eisenweberseide und 200 Gold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9239] = { title = "Gletscherhandschuhe", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Gletscherhandschuhe herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 4 Runenstoffballen, 4 Essenzen des Wassers, 2 Einheiten Eisenweberseide und 200 Gold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9240] = { title = "Gletscherweste", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, eine Gletscherweste herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", objectives = "Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 8 Runenstoffballen, 6 Essenzen des Wassers, 4 Einheiten Eisenweberseide und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
