quests[9319] = { title = "Licht im Dunkeln", description = "Wir sind nicht die Einzigen, die dieses Fest feiern, $n. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.\n\nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Schwarzfelsspitze selbst. Ich erwarte Eure Rückkehr.", objectives = "Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9320] = { title = "Erstklassiger Manatrank", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9321] = { title = "Major Healing Potion", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9322] = { title = "Glühende Feuer in Kalimdor", description = "Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise -- wie wäre es mit einem Ausflug?\n\nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterspring, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Un'Goro-Krater entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.", objectives = "Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Un'Goro-Krater und Winterspring auf. Kehrt dann zum Flammenbewahrer zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9323] = { title = "Glühende Feuer in den Östlichen Königreichen", description = "Das Fest der Flamme ist im ganzen Land verbreitet, $C. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.\n\nEines befindet sich genau nördlich von der Blackrockspitze. Die anderen liegen tief im Innern der östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den verwüsteten Landen.\n\nKehrt anschließend zu mir zurück.", objectives = "Reist zu den Lagern des Sonnenwendfests in den Verwüsteten Landen, den Östlichen Pestländern, dem Hinterland und der Sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9324] = { title = "Raubt die Flamme von Orgrimmar", description = "Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", objectives = "Bringt die Flamme von Orgrimmar zum Meister der Lehren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[9325] = { title = "Raubt die Flamme von Donnerfels", description = "Die Flamme, die dem Schamanen von Donnerfels entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", objectives = "Bringt die Flamme von Donnerfels zum Meister der Lehren.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
